// Keep the closing panel mounted briefly so its height can transition to zero.
function ModInlineDetails({expanded,label,children}:{expanded:boolean;label:string;children:React.ReactNode}){
 const [retained,setRetained]=useState(expanded);
 const content=useRef(children);
 if(expanded)content.current=children;
 useEffect(()=>{
  if(expanded){setRetained(true);return;}
  const timer=window.setTimeout(()=>setRetained(false),220);
  return ()=>window.clearTimeout(timer);
 },[expanded]);
 if(!expanded&&!retained)return null;
 return <section className={`mod-inline-details${expanded?" is-expanded":""}`} role="region" aria-label={label} inert={!expanded} aria-hidden={!expanded}><div className="mod-inline-clip"><div className="mod-inline-content">{content.current}</div></div></section>;
}

function Title({title,desc,action}:{title:string;desc:string;action?:React.ReactNode}){return <div className="page-title"><div><h1>{title}</h1><p>{desc}</p></div>{action}</div>;}
function Empty({text="暂无内容"}:{text?:string}){return <div className="empty"><b>暂无内容</b><span>{text}</span></div>;}
function Meta({label,value}:{label:string;value?:string}){return <div className="meta"><span>{label === "发布资产" ? "文件名" : label}</span><b>{value||"—"}</b></div>;}
function modSelectionKey(mod:any){return `${String(mod.kind)}:${String(mod.name).toLowerCase()}`;}
function versionNumbers(value:string){return value.match(/\d+/g)?.map(Number)??[];}
function compareModVersions(local:string,remote:string){const left=versionNumbers(local),right=versionNumbers(remote);for(let index=0;index<Math.max(left.length,right.length);index++){const a=left[index]??0,b=right[index]??0;if(a!==b)return a-b;}return 0;}
function modRemoteId(mod:any){return [mod.id,mod.name,mod.nameText,mod.fileName?.replace(/\.mm\.dll$/i,"")].filter(Boolean).map((value:any)=>String(value).toLowerCase());}
