function modCategory(mod:any){const remoteCategory=String(mod.remote?.category??mod.category??"").toLowerCase();if(modCategoryOrder.includes(remoteCategory))return remoteCategory;return bundledModCategories[String(mod.remote?.id??mod.name??"")]??"other";}
function remoteModTranslation(remote:any){const catalog=remoteModTranslations[String(remote?.id??"")];return {name:String(remote?.chineseName||catalog?.name||remote?.displayName||remote?.id||""),description:String(remote?.description||catalog?.description||"此 Mod 已发布，但暂未提供详细说明。")};}
function packageSize(value:number){if(value<1024)return `${value} B`;if(value<1024*1024)return `${(value/1024).toFixed(1)} KB`;if(value<1024*1024*1024)return `${(value/1024/1024).toFixed(1)} MB`;return `${(value/1024/1024/1024).toFixed(2)} GB`;}
function packageRate(value:number){return value>0?`${packageSize(value)}/秒`:"—";}
function packagePhase(phase:PackageProgress["phase"]){return phase==="downloading"?"下载中":phase==="verifying"?"校验中":phase==="extracting"?"解压中":phase==="installing"?"安装中":phase==="completed"?"已完成":phase==="cancelled"?"已取消":phase==="error"?"失败":"处理中";}
