const segaFieldOrder:Record<string,readonly string[]>={
 vfs:["amfs","option","appdata"],dns:["default","AimeDB","replaceHost"],netenv:["enable"],keychip:["id","subnet"],
 aimeio:["path"],mu3io:["path"],aime:["enable","aimePath","aimeGen","felicaPath","portNo","scan"],
 io4:["enable","mouse","keyboard","test","service","coin","xinput","left1","left2","left3","leftSide","rightSide","right1","right2","right3","leftMenu","rightMenu"],
 led15093:["enable"],led:["cabLedOutputPipe","cabLedOutputSerial","controllerLedOutputPipe","controllerLedOutputSerial","serialPort","serialBaud"],
 system:["enable","freeplay","dipsw1"],gfx:["enable"],unity:["enable","targetAssembly"]
};
function orderSegaEntries(section:string,entries:any[]){const order=segaFieldOrder[section.toLowerCase()]??[];const position=(entry:any)=>{const index=order.findIndex(key=>key.toLowerCase()===String(entry.key).toLowerCase());return index<0?Number.MAX_SAFE_INTEGER:index;};return [...entries].sort((left,right)=>position(left)-position(right)||String(left.key).localeCompare(String(right.key),undefined,{numeric:true}));}

export function Sega({config,root,onChanged,focusMachineId}:{config:Config|null;root:string;onChanged():Promise<void>;focusMachineId?:string}) {
 const file=(config?.files??[]).find((item:any)=>item.kind==="SegaTools");
 const profiles=useSegatoolsProfiles(root,file?.contentHash);
 const entries=(file?.entries??[]).filter((entry:any)=>entry.isKnown!==false&&!configPresentation(entry).hidden&&!["dns","netenv","keychip"].includes(String(entry.section).toLowerCase()));
 const groupedEntries=new Map<string,any[]>();entries.forEach((entry:any)=>{const group=groupedEntries.get(entry.section)??[];group.push(entry);groupedEntries.set(entry.section,group);});
 const sectionLabels:Record<string,string>={system:"系统",gfx:"图形 Hook",unity:"Unity Hook"};
 const representedSections=new Set<string>(segaDisplayGroups.flatMap(group=>group.sections));
 const sections=[
  ...segaDisplayGroups.filter(group=>group.sections.some(name=>groupedEntries.has(name))).map(group=>({name:group.id,label:group.label,entries:group.sections.flatMap(name=>orderSegaEntries(name,groupedEntries.get(name)??[]))})),
  ...Array.from(groupedEntries.keys()).filter(name=>!representedSections.has(name)).sort((left,right)=>left.localeCompare(right)).map(name=>({name,label:sectionLabels[name]??name,entries:orderSegaEntries(name,groupedEntries.get(name)??[])}))
 ];
 const [backups,setBackups]=useState<any[]>([]);const [backupOpen,setBackupOpen]=useState(false);const [restoreCandidate,setRestoreCandidate]=useState<any>();const [restoreError,setRestoreError]=useState("");const [restoring,setRestoring]=useState(false);const [saved,setSaved]=useState(false);const [keyboardInputEnabled,setKeyboardInputEnabled]=useState(true);const savedTimer=useRef<number|undefined>(undefined);
 const notifySaved=()=>{window.clearTimeout(savedTimer.current);setSaved(true);savedTimer.current=window.setTimeout(()=>setSaved(false),2000);};
 const loadBackups=async()=>{if(!root||!window.ogk.segatoolsBackups)return;setBackups(await window.ogk.segatoolsBackups(root));};
 useEffect(()=>{let active=true;if(!root||!window.ogk.backupSegatools)return;void window.ogk.backupSegatools(root).then(items=>{if(active)setBackups(items);}).catch(()=>{});return()=>{active=false;};},[root]);
 useEffect(()=>{const keyboard=(file?.entries??[]).find((entry:any)=>entry.section==="io4"&&entry.key==="keyboard");if(keyboard)setKeyboardInputEnabled(String(keyboard.value)==="1");},[file]);
 const restore=async()=>{if(!restoreCandidate||restoring)return;setRestoring(true);setRestoreError("");try{await window.ogk.restoreSegatoolsBackup({gameRoot:root,name:restoreCandidate.name});setRestoreCandidate(undefined);setBackupOpen(false);await loadBackups();await onChanged();notifySaved();}catch(error){setRestoreError(error instanceof Error?error.message:"恢复配置失败。");}finally{setRestoring(false);}};
 const action=<div className="sega-actions"><div className="backup-menu"><button type="button" onClick={()=>{setBackupOpen(value=>!value);void loadBackups();}}>恢复自动备份</button>{backupOpen&&<div className="backup-popover">{backups.length?backups.map(item=><button type="button" key={item.name} onClick={()=>setRestoreCandidate(item)}>{new Date(item.createdAt).toLocaleString()}</button>):<span>暂无自动备份</span>}</div>}</div></div>;
 return <div className="sega-page"><div className="sega-titlebar"><Title title="Segatools 配置" desc="当前机台和设备修改立即应用；其他机台只保存本地档案。" action={action}/></div>{saved&&<div className="save-toast" role="status">已保存配置</div>}{restoreCandidate&&<div className="confirm-backdrop" role="presentation"><section className="confirm-dialog" role="dialog" aria-modal="true" aria-label="确认恢复备份"><h2>恢复自动备份？</h2><p>当前 segatools.ini 将被所选备份覆盖，此操作无法撤销。</p>{restoreError&&<p className="config-error" role="alert">{restoreError}</p>}<div><button type="button" disabled={restoring} onClick={()=>{setRestoreCandidate(undefined);setRestoreError("");}}>取消</button><button type="button" className="primary" disabled={restoring} onClick={()=>void restore()}>{restoring?"正在恢复…":"确认覆盖"}</button></div></section></div>}
 <article className="surface config-table"><div className="config-scroll">
 {!file?<Empty text={root?"未找到 Segatools 配置。":"请先扫描游戏目录。"}/>:<div className="entry-list"><SegatoolsMachinePanel key={root} root={root} file={file} profiles={profiles} focusMachineId={focusMachineId} onApplied={onChanged} renderEntry={({entry,onPersist,disabled})=><ConfigEntry key={`${entry.section}.${entry.key}`} file={file} entry={entry} root={root} persistOverride={onPersist} disabled={disabled} onSaved={async()=>{}}/>}/>{sections.map((section:any)=><section className="config-section" key={section.name}><h2 className="config-section-title">{section.label}</h2>{section.name==="aime"&&<VirtualAimeCard key={root} root={root} profiles={profiles} enabled={String(section.entries.find((entry:any)=>String(entry.key).toLowerCase()==="enable")?.value??"1")==="1"} onApplied={onChanged}/>} {section.entries.map((entry:any,i:number)=><ConfigEntry key={i} file={file} entry={entry} root={root} keyboardInputEnabled={keyboardInputEnabled} onKeyboardInputChange={setKeyboardInputEnabled} onSaved={async()=>{await onChanged();notifySaved();}}/>)}</section>)}</div>}
 </div></article></div>;
}
