const virtualKeyLabels:Record<number,string>={1:"鼠标左键",2:"鼠标右键",8:"Backspace",9:"Tab",13:"Enter",16:"Shift",17:"Ctrl",18:"Alt",19:"Pause",20:"Caps Lock",27:"Esc",32:"Space",33:"Page Up",34:"Page Down",35:"End",36:"Home",37:"←",38:"↑",39:"→",40:"↓",44:"Print Screen",45:"Insert",46:"Delete",91:"Win",92:"Win",93:"Menu",144:"Num Lock",145:"Scroll Lock",186:";",187:"=",188:",",189:"-",190:".",191:"/",192:"`",219:"[",220:"\\",221:"]",222:"'"};
function virtualKeyLabel(value:string){const code=Number.parseInt(value,0);if(!Number.isFinite(code))return value;if(code>=0x30&&code<=0x39||code>=0x41&&code<=0x5a)return String.fromCharCode(code);if(code>=0x60&&code<=0x69)return `Num ${code-0x60}`;if(code>=0x70&&code<=0x87)return `F${code-0x6f}`;return virtualKeyLabels[code]??`0x${code.toString(16).toUpperCase().padStart(2,"0")}`;}
function eventVirtualKey(event:React.KeyboardEvent){const key=event.key;const special:Record<string,number>={Backspace:8,Tab:9,Enter:13,Shift:16,Control:17,Alt:18,Pause:19,CapsLock:20,Escape:27," ":32,PageUp:33,PageDown:34,End:35,Home:36,ArrowLeft:37,ArrowUp:38,ArrowRight:39,ArrowDown:40,PrintScreen:44,Insert:45,Delete:46,NumLock:144,ScrollLock:145,";":186,"=":187,",":188,"-":189,".":190,"/":191,"`":192,"[":219,"\\":220,"]":221,"'":222};if(special[key]!==undefined)return special[key];if(/^F(?:[1-9]|1[0-9]|2[0-4])$/.test(key))return 0x70+Number(key.slice(1))-1;if(/^[a-zA-Z0-9]$/.test(key))return key.toUpperCase().charCodeAt(0);if(event.code.startsWith("Numpad")&&/^Numpad\d$/.test(event.code))return 0x60+Number(event.code.at(-1));return null;}
