 const localMods=installedMods.map((mod:any)=>{const remote=modRemoteId(mod).map(id=>remoteById.get(id)).find(Boolean);const remoteId=remote?.id.toLowerCase();const needsUpdate=Boolean(remote&&compareModVersions(String(mod.version??""),remote.version)<0);return {...mod,remote,remoteState:remote?(locallyUpdatedRemoteIds.has(remoteId??"")?"current":needsUpdate?"update":"current"):"unknown",needsUpdate};});
