 const toggle=async()=>{if(!selected||selected.remoteOnly||selected.optimisticInstalled||!root||busy)return;setBusy(true);setError("");try{await window.ogk.toggleMod({gameRoot:root,mod:selected});await onChanged();}catch(caught){setError(caught instanceof Error?caught.message:"Mod 开关切换失败。");}finally{setBusy(false);}};
