 const startModDownload=(mod:any)=>{if(!mod?.remote||!root||isDownloadActive(downloads[mod.remote.id]))return;const remoteId=mod.remote.id;const downloadId=`mod-${remoteId}-${Date.now()}`;const initial:PackageProgress={downloadId,kind:"mod",id:remoteId,phase:"downloading",received:0,total:mod.remote.size,percent:0,speed:0,message:"准备下载…"};setDownloads(current=>({...current,[remoteId]:initial}));onDownloadStarted?.(initial);setManifestError("");void window.ogk.downloadPackage({downloadId,kind:"mod",id:remoteId,root}).then(()=>{setLocallyUpdatedRemoteIds(current=>new Set(current).add(remoteId.toLowerCase()));setDownloads(current=>{if(current[remoteId]?.downloadId!==downloadId)return current;const next={...current};delete next[remoteId];return next;});}).catch(caught=>{const message=caught instanceof Error?caught.message:"Mod 下载或安装失败。";if(message.includes("下载已取消")){setDownloads(current=>{const next={...current};delete next[remoteId];return next;});return;}setDownloads(current=>current[remoteId]?.downloadId===downloadId?{...current,[remoteId]:{...current[remoteId],phase:"error",error:message,message}}:current);});};
